def event(self, event, parsed=None):
    handler = self.dispatch.get(event['op'])
    if handler is None:
        return _ERR
    outcome = handler(event, parsed)
    if outcome is not _ERR and outcome[0] != INSPECT:
        # Any successful mutation invalidates the cached snapshot.
        self.version += 1
    return outcome

def _unit(self, ident):
    unit = self.units.get((ident[0], ident[1]))
    if unit is None or unit.gen != ident[2]:
        return None
    return unit

